effect.shader:
void main(){
vec2 uv=acScreenNorm,p=uv-0.5;
float ca=cos(axis),sa=sin(axis); mat2 r=mat2(ca,-sa,sa,ca);
vec2 a=r*p; float cf=cos(flip),sf=sin(flip);
float z=a.x*sf, den=max(0.16,1.0+z*perspective);
vec2 q=vec2(a.x/max(abs(cf),0.035),a.y/den);
if(cf<0.0) q.x=-q.x;
q=mat2(ca,sa,-sa,ca)*q+0.5;
float valid=step(0.0,q.x)*step(q.x,1.0)*step(0.0,q.y)*step(q.y,1.0);
vec4 src=texture2DCv(inputImg.texture,uv),dst=texture2DCv(inputImg.texture,clamp(q,0.0,1.0));
float face=mix(backFade,1.0,step(0.0,cf));
dst.rgb*=face*mix(1.0,0.35+0.65*abs(cf),edgeShade);
gl_FragColor=mix(src,dst,mixAmount*valid);
}
